INSERT INTO public.daily_journals (user_id, journal_date, day_summary, what_went_wrong, actionable_improvements, energy_rating)
VALUES (3, '2026-11-24', 'Followed the Three-Meal Diet Plan strictly without snacking. Had ACV 15m before Meal 1 & Meal 3. Great mind-muscle connection on Free Squats and Hack Squats.', 'Slight tightness in right hip flexor during Forward Lunges. Need to spend 3 extra minutes on 90/90 hip openers during warm-up.', 'Drink 1L water with electrolytes before starting Day 2 Back & Biceps. Maintain 3-meal timing without deviation.', 9);
